@app.cell(hide_code=True)
def _(DEVELOPMENT, get_code, get_connection, get_receipts, install_runtime, mo, set_receipts, support, ui):
    mo.stop(not install_runtime.value)
    try:
        _ctx, _code = get_connection(), get_code()
        if not _ctx: raise ValueError("Connect first")
        if not all(k in _code for k in ["lookup", "runtime", "schema"]): raise ValueError("Run all free cells once to initialize the code registry, then retry registration. This does not run the employee.")
        if not all(r["passed"] for r in support.tool_checks(_code["lookup"], DEVELOPMENT)): raise ValueError("Pass the local invoice checks first")
        support.loop_checks(_code["dispatch"], _code["append"])
        _receipt = _ctx["client"].register_runtime(_code["runtime"], support.source(_code["lookup"]), _code["schema"])
        _test = _ctx["client"].test_tool()
        _ctx["journal"].put("registration", _receipt)
        set_receipts({**get_receipts(), "registration": _receipt, "tool_test": _test})
        _audit = _ctx["client"].audit(_test["execution_id"])
        _traces = support.export_completed_traces(_ctx, _code, [_audit["run"]])
        mo.output.replace(mo.vstack([mo.md("**Your code ran in a remote Sandbox.** Match its registered source fingerprint with the receipt, then open the lookup calls in Agent Lens."), mo.Html(ui.trace_results(_traces)), mo.accordion({"Sandbox receipt and execution audit": mo.Html(ui.receipt({"registration": _receipt["fingerprint"], "test": _test, "audit": _audit}))})]))
    except Exception as _error:
        mo.output.replace(mo.callout(str(_error), kind="danger"))
    return


