@app.cell(hide_code=True)
def _(Harness, fingerprint, get_code, get_connection, json, mo, publish_final, support, ui):
    mo.stop(not publish_final.value)
    try:
        _ctx, _code = get_connection(), get_code()
        _snapshot = _ctx["client"].snapshot()
        _runs = [r for r in _snapshot["runs"] if r["stage"].startswith("eval_")]
        if len(_runs) != 12 or not _snapshot["graded"]: raise ValueError("Complete all 12 executions and grading first")
        _links = []
        _comparison_rows = []
        for _stage in ["eval_original", "eval_manual", "eval_frozen"]:
            _rows = []
            for _run in [r for r in _runs if r["stage"] == _stage]:
                _trace = support.capture_trace(_ctx["client"].audit(_run["id"]), _ctx["project"], _ctx["session"], _code["instrument"], _ctx["journal"], version=_code["instrumentation_version"])
                _judge = next((j for j in _snapshot["judgments"] if j["execution_id"] == _run["id"]), None)
                # Preserve the native final rubric in the evidence. It is not the learner's boolean judge.
                _row = _code["row"](_run, _run.get("scores", {}).get("task_success"), None, _trace["url"])
                _row["output"]["native_judge"] = json.dumps(_judge)
                if _judge and _judge.get("status") == "complete":
                    for _criterion, _item in _judge.get("outcome", {}).get("criteria", {}).items():
                        _row["scores"]["native_" + _criterion] = _item["score"]
                _row["output"]["scorer_origin"] = "protected final scorer"
                _rows.append(_row)
                _comparison_rows.append({"case": _run["case_id"], "version": _stage, **_row["scores"], "Agent Lens": _trace["url"], "execution": _run["id"]})
            _suite = "protected-final-v1"
            _key = ["publication", _stage, fingerprint(_rows), _code["publication_version"]]
            _link = support.publish_checkpoint(_ctx["journal"], _key, lambda: _code["publish"](_ctx["project"], _ctx["scope_id"], _stage, _rows, Harness(**_run["harness"]).files(), _suite))
            _links.append(_link)
        _ctx["journal"].put("final-publications", _links)
        _view = _ctx["journal"].once(["comparison", fingerprint(_links)], lambda: _code["comparison"](_ctx["project"], _links))
        _ctx["journal"].put("final-view", _view)
        _ctx["journal"].put("final-comparison-rows", _comparison_rows)
        mo.output.replace(mo.vstack([mo.Html(ui.publication_summary(_links, _view)), mo.md("**Case-by-case results** · These are the saved native scores. Missing judgments remain missing. This notebook table is also available when native EvalTables is unavailable."), mo.ui.table(_comparison_rows), mo.Html(ui.receipt(_links))]))
    except Exception as _error:
        mo.output.replace(mo.callout(str(_error), kind="danger"))
    return


